--
-- Name: cleanup_expired_casual_data(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_expired_casual_data() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM applications a
    USING resumes r
    WHERE a.resume_id = r.id
      AND r.user_id IS NULL
      AND r.expires_at IS NOT NULL
      AND r.expires_at <= NOW();

    DELETE FROM resumes r
    WHERE r.user_id IS NULL
      AND r.expires_at IS NOT NULL
      AND r.expires_at <= NOW();

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.cleanup_expired_casual_data() OWNER TO postgres;

--
-- Name: link_resumes_and_applications_on_user_signup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.link_resumes_and_applications_on_user_signup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE resumes
    SET user_id = NEW.id
    WHERE LOWER(candidate_email) = LOWER(NEW.email)
      AND user_id IS NULL;

    UPDATE applications
    SET user_id = NEW.id
    WHERE LOWER(candidate_email) = LOWER(NEW.email)
      AND user_id IS NULL;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.link_resumes_and_applications_on_user_signup() OWNER TO postgres;

