--
-- Name: idx_applications_candidate_email; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_candidate_email ON public.applications USING btree (candidate_email);


--
-- Name: idx_applications_job_score; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_job_score ON public.applications USING btree (job_id, match_score DESC NULLS LAST);


--
-- Name: idx_applications_job_status; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_job_status ON public.applications USING btree (job_id, status);


--
-- Name: idx_applications_overqualified; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_overqualified ON public.applications USING btree (is_overqualified) WHERE (is_overqualified = true);


--
-- Name: idx_applications_user; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_user ON public.applications USING btree (user_id);


--
-- Name: idx_applications_user_applied_at; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_applications_user_applied_at ON public.applications USING btree (user_id, applied_at DESC);


--
-- Name: idx_jobs_area_modality; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_area_modality ON public.jobs USING btree (area, modality);


--
-- Name: idx_jobs_created_at; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_created_at ON public.jobs USING btree (created_at DESC);


--
-- Name: idx_jobs_deadline; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_deadline ON public.jobs USING btree (deadline);


--
-- Name: idx_jobs_embedding_hnsw; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_embedding_hnsw ON public.jobs USING hnsw (embedding public.vector_cosine_ops);


--
-- Name: idx_jobs_recruiter; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_recruiter ON public.jobs USING btree (recruiter_id);


--
-- Name: idx_jobs_status; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_jobs_status ON public.jobs USING btree (status);


--
-- Name: idx_resumes_embedding_hnsw; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_resumes_embedding_hnsw ON public.resumes USING hnsw (embedding public.vector_cosine_ops);


--
-- Name: idx_resumes_expires_at; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_resumes_expires_at ON public.resumes USING btree (expires_at) WHERE (expires_at IS NOT NULL);


--
-- Name: idx_resumes_updated_at; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_resumes_updated_at ON public.resumes USING btree (updated_at DESC);


--
-- Name: idx_skills_cache_embedding_hnsw; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_skills_cache_embedding_hnsw ON public.skills_cache USING hnsw (embedding public.vector_cosine_ops);


--
-- Name: idx_skills_cache_normalized_term; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_skills_cache_normalized_term ON public.skills_cache USING btree (normalized_term);


--
-- Name: idx_users_created_at; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX idx_users_created_at ON public.users USING btree (created_at DESC);


